    "The automated AI pipeline (Indic OCR, MuRIL NER, PostGIS boundary match, and risk scoring) completes within 2 to 5 minutes. Subsequent human inspection by the Village Revenue Officer (Patwari) and Girdawar typically takes 24 to 48 business hours.": "স্বয়ংক্রিয় এআই পাইপলাইন (ইন্ডিক ওসিআর, MuRIL এনইআর, পোস্টজিআইএস সীমানা মিল এবং ঝুঁকি স্কোরিং) ২ থেকে ৫ মিনিটের মধ্যে সম্পন্ন হয়। গ্রাম রাজস্ব কর্মকর্তা (পাটোয়ারী) এবং গিরদাবর দ্বারা পরবর্তী মানবিক পরিদর্শনে সাধারণত ২৪ থেকে ৪৮ কার্যঘণ্টা সময় লাগে।",
    "What documents are eligible for upload?": "আপলোডের জন্য কোন নথিগুলি যোগ্য?",
    "Registered Sale Deeds (Kraya Patram), Rythu Seva / Pattadar Passbooks, Encumbrance Certificates (EC), Partition Deeds, Gift Settlement Deeds, and Succession Certificates in PDF, JPG, or PNG format (up to 15MB).": "নিবন্ধিত বিক্রয় দলিল (ক্রয় পত্রম), রায়থু সেবা / পাট্টাদার পাসবুক, দায়বদ্ধতা শংসাপত্র (ইসি), বণ্টন দলিল, হেবা/দানপত্র দলিল এবং উত্তরাধিকার শংসাপত্র PDF, JPG বা PNG ফরম্যাটে (১৫MB পর্যন্ত)।",
    "What should I do if my document is flagged with \"Correction Required\"?": "আমার নথিতে \"সংশোধন প্রয়োজন\" চিহ্নিত হলে আমার কী করা উচিত?",
    "Click the \"Re-upload Corrected Scan\" button on your application page. Common reasons include low scan resolution (<300 DPI), missing schedule pages, or poor contrast on old stamp paper.": "আপনার আবেদন পৃষ্ঠায় \"সংশোধিত স্ক্যান পুনরায় আপলোড করুন\" বোতামে ক্লিক করুন। সাধারণ কারণগুলির মধ্যে রয়েছে কম স্ক্যান রেজোলিউশন (<300 DPI), অনুপস্থিত সময়সূচী পৃষ্ঠাগুলি, বা পুরানো স্ট্যাম্প পেপারে দুর্বল বৈসাদৃশ্য।",
    "How does the \"Share with Bank\" feature work?": "\"ব্যাংকের সাথে শেয়ার করুন\" বৈশিষ্ট্যটি কীভাবে কাজ করে?",
    "Once your mutation is approved by the Tehsildar, you can generate an encrypted, time-limited 7-day token link. When shared with your lending bank officer, they can directly verify your title authenticity, cadastral coordinates, and non-encumbrance status from government servers without physical visits.": "একবার আপনার নামপত্তন তহসিলদার দ্বারা অনুমোদিত হলে, আপনি একটি এনক্রিপ্ট করা, সময়-সীমিত ৭ দিনের টোকেন লিঙ্ক তৈরি করতে পারেন। আপনার ঋণ প্রদানকারী ব্যাংক কর্মকর্তার সাথে শেয়ার করা হলে, তারা সরাসরি সরকারি সার্ভার থেকে শারীরিক পরিদর্শন ছাড়াই আপনার মালিকানার সত্যতা, ক্যাডাস্ট্রাল স্থানাঙ্ক এবং দায়হীন স্থিতি যাচাই করতে পারেন।",
    "Is Bhooraksha available in regional Indian languages?": "ভূরক্ষা কি আঞ্চলিক ভারতীয় ভাষায় উপলব্ধ?",
    "Yes, Bhooraksha supports 18 official Indian languages: English, Hindi, Bengali, Tamil, Telugu, Marathi, Gujarati, Kannada, Malayalam, Odia, Punjabi, Assamese, Urdu, Sanskrit, Konkani, Maithili, Kashmiri, and Nepali.": "হ্যাঁ, ভূরক্ষা ১৮টি সরকারী ভারতীয় ভাষা সমর্থন করে: ইংরেজি, হিন্দি, বাংলা, তামিল, তেলেগু, মারাঠি, গুজরাটি, কন্নড়, মালায়ালম, ওড়িয়া, পাঞ্জাবি, অসমীয়া, উর্দু, সংস্কৃত, কোঙ্কনি, মৈথিলি, কাশ্মীরি এবং নেপালি।",
