    "gis.dashboard.subtitle": "ഭൂനക്ഷ ജിഐഎസിനെതിരെ കഡാസ്ട്രൽ അതിർത്തികൾ പരിശോധിക്കുക, സബ്-മീറ്റർ ബഹുഭുജ ഓവർലാപ്പുകൾ തിരിച്ചറിയുക, അതിർത്തി കോർഡിനേറ്റുകൾ ക്രമീകരിക്കുക, അല്ലെങ്കിൽ ഡിജിപിഎസ് ഫീൽഡ് സർവേകൾ ഷെഡ്യൂൾ ചെയ്യുക.",
