    "The automated AI pipeline (Indic OCR, MuRIL NER, PostGIS boundary match, and risk scoring) completes within 2 to 5 minutes. Subsequent human inspection by the Village Revenue Officer (Patwari) and Girdawar typically takes 24 to 48 business hours.": "خودکار AI پائپ لائن (انڈک OCR، MuRIL NER، PostGIS حد بندی مِلاو، تہٕ خطرہٕ سکور) 2 پؠٹھ 5 منٹن مَنٛز مکمل گژھان چُھ۔ پٹواری تہٕ گرداور سٕنٛد طرفہٕ اِنسانی جانچس مَنٛز چُھ عام طور 24 پؠٹھ 48 کاروباری گَنٛٹہٕ لگان।",
    "What documents are eligible for upload?": "اپ لوڈ خٲطرٕ کَم دستاویزات چھِ اہل؟",
    "Registered Sale Deeds (Kraya Patram), Rythu Seva / Pattadar Passbooks, Encumbrance Certificates (EC), Partition Deeds, Gift Settlement Deeds, and Succession Certificates in PDF, JPG, or PNG format (up to 15MB).": "رجسٹرڈ بیع نامہ (کرایہ پترم)، رائیتھو سیوا / پٹہ دار پاس بکس، انکمبرنس سرٹیفکیٹ (EC)، تقسیم نامہ، ہبہ نامہ تہٕ جانشینی سرٹیفکیٹ PDF، JPG یا PNG فارمیٹس مَنٛز (15MB تام)۔",
    "What should I do if my document is flagged with \"Correction Required\"?": "اگر مؠنِس دستاویزس پؠٹھ \"درُستگی ضۆروٗری\" نِشان لگٲوِتھ چُھ تَلِہ کیا کَرُن؟",
    "Click the \"Re-upload Corrected Scan\" button on your application page. Common reasons include low scan resolution (<300 DPI), missing schedule pages, or poor contrast on old stamp paper.": "تہنٛزِ درخواست پؠٹھ \"درُست کٔرِتھ سکین دوبارہ اپ لوڈ کٔریو\" بٹنَس پؠٹھ کِلک کٔریو۔ عام وجوہات مَنٛز چھِ کم سکین ریزولیوشن (<300 DPI)، لاپتہ شیڈول صفہٕ، یا پرانہِ سٹامپ پیپرس پؠٹھ خراب کنٹراسٹ شٲمِل।",
    "How does the \"Share with Bank\" feature work?": "\"بینکَس سٟتؠ شیئر کٔریو\" فیچر کِتھ کَنِ چُھ کٲم کران؟",
    "Once your mutation is approved by the Tehsildar, you can generate an encrypted, time-limited 7-day token link. When shared with your lending bank officer, they can directly verify your title authenticity, cadastral coordinates, and non-encumbrance status from government servers without physical visits.": "ییلہِ تۄہُنٛد اِنتقال تحصیلدار سندِ طرفہٕ منظور گژھِ، تَتھ وقتہٕ ہیٚکِو تۄہی اکھ اینکرپٹڈ، 7 دۄہَن ہُنٛد وقتی ٹوکن لِنک بَنٲوِتھ۔ ییلہِ یہِ پننِس قرض دِنہٕ وٲلِس بینک آفِسرَس سٟتؠ شیئر کَرنہٕ یِیہِ، تِمہِ ہیٚکَن کُنہِ دفتری چکر بغیر براہِ راست سرکٲری سرور پؠٹھٕ تۄہنٛزِ مِلکیتٕچ اصلیت، کوآرڈینیٹس تہٕ بوجھ مُکت حالتٕچ تصدیق کٔرِتھ।",
    "Is Bhooraksha available in regional Indian languages?": "کیا بھورکشا علاقٲیی ہِندوستٲنؠ زبانن مَنٛز دٔستیاب چُھ؟",
    "Yes, Bhooraksha supports 18 official Indian languages: English, Hindi, Bengali, Tamil, Telugu, Marathi, Gujarati, Kannada, Malayalam, Odia, Punjabi, Assamese, Urdu, Sanskrit, Konkani, Maithili, Kashmiri, and Nepali.": "آہنو، بھورکشا چُھ 18 سرکٲری ہِندوستٲنؠ زبانن ہِنٛز حِمایت کران: اَنٛگریزی، ہِندی، بَنٛگٲلؠ، تَمِل، تیلگو، مراٹھی، گُجرٲتؠ، کَنَّڑ، مَلیالم، اوڈیا، پَنٛجٲبؠ، آسٲمؠ، اُردوٗ، سَنسکرٕت، کوکنؠ، مَیتھلی، کٲشُر تہٕ نیپٲلؠ।",
